import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";var i=JSON.parse(`{"title":"課題管理の5つの核心原則","description":"Jiraを効率的に使用するための核心原則を紹介します。✅ 課題割り当ての法則、✅ 必須コメントガイド、✅ ステータス管理のノウハウを通じてプロジェクトの透明性とチームの生産性を高める方法を確認してください。チームコラボレーションのためのガイドです。","frontmatter":{"title":"課題管理の5つの核心原則","description":"Jiraを効率的に使用するための核心原則を紹介します。✅ 課題割り当ての法則、✅ 必須コメントガイド、✅ ステータス管理のノウハウを通じてプロジェクトの透明性とチームの生産性を高める方法を確認してください。チームコラボレーションのためのガイドです。","head":[["meta",{"name":"keywords","content":"Jira, 課題管理, Jiraの使い方, プロジェクト管理, コラボレーションツール, 割り当ての原則, コメント, ステータス管理, ワークフロー, 生産性向上"}],["meta",{"property":"og:title","content":"課題管理の5つの核心原則 | 効果的なプロジェクト管理法"}],["meta",{"property":"og:description","content":"課題を効率的に使用するための核心原則を紹介します。✅ 課題割り当ての法則、✅ 必須コメントガイド、✅ ステータス管理のノウハウを通じてプロジェクトの透明性とチームの生産性を高める方法を確認してください。チームコラボレーションのためのガイドです。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/PrinciplesForIssueUsage.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/PrinciplesForIssueUsage.html"}]],"sort":6000},"headers":[],"relativePath":"ja/agile/PrinciplesForIssueUsage.md","filePath":"ja/agile/PrinciplesForIssueUsage.md","lastUpdated":1786257982000}`),a={name:`ja/agile/PrinciplesForIssueUsage.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h2 id="課題を効果的に使用するための核心原則" tabindex="-1">課題を効果的に使用するための核心原則 <a class="header-anchor" href="#課題を効果的に使用するための核心原則" aria-label="Permalink to “課題を効果的に使用するための核心原則”">​</a></h2><h3 id="_1-割り当ての原則" tabindex="-1">1. <strong>割り当ての原則</strong> <a class="header-anchor" href="#_1-割り当ての原則" aria-label="Permalink to “1. 割り当ての原則”">​</a></h3><ul><li>✅ <strong>現在の担当者に割り当てる</strong>: 課題は常に現在実際に作業を進めている人に割り当てられるべきです。</li><li>✅ <strong>割り当て後すぐに確認</strong>: 課題が割り当てられたら、担当者はすぐに確認し、作業を開始するかどうかを明示します。</li><li>❌ <strong>空の割り当て禁止</strong>: 担当者が指定されていない課題は放置されやすいです。</li></ul><h3 id="_2-コメント作成の原則" tabindex="-1">2. <strong>コメント作成の原則</strong> <a class="header-anchor" href="#_2-コメント作成の原則" aria-label="Permalink to “2. コメント作成の原則”">​</a></h3><ul><li>✅ <strong>作業完了時のコメント必須</strong>: 作業完了後は、必ず処理結果のコメントを追加します。</li><li>✅ <strong>進捗状況の共有</strong>: 途中の進捗状況をコメントで共有します（特に長期作業の場合）。</li><li>✅ <strong>課題移動時のコメント</strong>: ステータス変更時（例：進行中 → 完了）、変更理由を明示します。</li><li>❌ <strong>無意味なコメントの禁止</strong>: 「確認しました」、「進行中」などだけを繰り返さないようにします。</li></ul><h3 id="_3-ステータス管理の原則" tabindex="-1">3. <strong>ステータス管理の原則</strong> <a class="header-anchor" href="#_3-ステータス管理の原則" aria-label="Permalink to “3. ステータス管理の原則”">​</a></h3><ul><li>✅ <strong>リアルタイムのステータス更新</strong>: 作業状況に応じてステータスを即座に更新します。</li><li>✅ <strong>明確なステータスの定義</strong>: チームごとにステータスの意味を明確に定義し、一貫して使用します。</li><li>❌ <strong>放置状態の禁止</strong>: 「進行中」のステータスで長期間放置しないようにします。</li></ul><h3 id="_4-課題作成の原則" tabindex="-1">4. <strong>課題作成の原則</strong> <a class="header-anchor" href="#_4-課題作成の原則" aria-label="Permalink to “4. 課題作成の原則”">​</a></h3><ul><li>✅ <strong>明確なタイトル</strong>: 何をするのかが一目でわかるタイトルを使用します。</li><li>✅ <strong>詳細な説明</strong>: 再現手順、予想される結果、実際の結果を含む詳細内容を記述します。</li><li>✅ <strong>必須フィールドの入力</strong>: 優先順位、予想所要時間、コンポーネントなどの必須フィールドを必ず入力します。</li><li>❌ <strong>不明確な表現の禁止</strong>: 「問題がある」、「直してください」などの不明確な表現を使用しないようにします。</li></ul><h3 id="_5-ワークフロー遵守の原則" tabindex="-1">5. <strong>ワークフロー遵守の原則</strong> <a class="header-anchor" href="#_5-ワークフロー遵守の原則" aria-label="Permalink to “5. ワークフロー遵守の原則”">​</a></h3><ul><li>✅ <strong>定義されたワークフローに従う</strong>: チームで決めたワークフローを厳格に遵守します。</li><li>✅ <strong>レビュープロセスの遵守</strong>: コードレビュー、QAプロセスなどの必要な手順を省略しないようにします。</li><li>✅ <strong>一貫したプロセス</strong>: すべてのチームメンバーが同じプロセスに従って作業します。</li></ul><h2 id="例-理想的な課題処理フロー" tabindex="-1">例：理想的な課題処理フロー <a class="header-anchor" href="#例-理想的な課題処理フロー" aria-label="Permalink to “例：理想的な課題処理フロー”">​</a></h2><ol><li><strong>課題作成</strong> → 担当者割り当て + 優先順位設定</li><li><strong>作業開始</strong> → ステータス「進行中」に変更 + 開始コメント</li><li><strong>進行中</strong> → 途中の進捗状況コメントを作成 (必要な場合)</li><li><strong>作業完了</strong> → ステータス「完了」に変更 + <strong>詳細な処理結果コメント</strong></li><li><strong>レビューが必要な場合</strong> → ステータス「レビュー中」に変更 + レビュアー割り当て</li></ol>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};